def calc(expr: str) -> int | str:
    class _CalcError(Exception):
        pass

    tokens: list[int | str] = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isspace():
            i += 1
        elif ch.isdigit():
            start = i
            while i < n and expr[i].isdigit():
                i += 1
            if i - start > 4300:
                val = 0
                for k in range(start, i, 1000):
                    chunk = expr[k : min(k + 1000, i)]
                    val = val * (10 ** len(chunk)) + int(chunk)
                tokens.append(val)
            else:
                tokens.append(int(expr[start:i]))
        else:
            tokens.append(ch)
            i += 1

    pos = 0
    num_tokens = len(tokens)

    def parse_atom() -> int:
        nonlocal pos
        tok = tokens[pos]
        if tok == "(":
            pos += 1
            val = parse_add()
            pos += 1
            return val
        pos += 1
        return tok  # type: ignore[return-value]

    def parse_unary() -> int:
        nonlocal pos
        pairs: list[tuple[bool, int]] = []
        while True:
            neg = False
            while pos < num_tokens and tokens[pos] == "-":
                neg = not neg
                pos += 1
            base = parse_atom()
            pairs.append((neg, base))
            if pos < num_tokens and tokens[pos] == "^":
                pos += 1
            else:
                break

        neg, res = pairs[-1]
        if neg:
            res = -res
        for idx in range(len(pairs) - 2, -1, -1):
            if res < 0:
                raise _CalcError
            neg, base = pairs[idx]
            res = base ** res
            if neg:
                res = -res
        return res

    def parse_mul() -> int:
        nonlocal pos
        val = parse_unary()
        while pos < num_tokens and tokens[pos] in ("*", "/", "%"):
            op = tokens[pos]
            pos += 1
            rhs = parse_unary()
            if op == "*":
                val *= rhs
            elif op == "/":
                if rhs == 0:
                    raise _CalcError
                q = abs(val) // abs(rhs)
                val = -q if (val < 0) ^ (rhs < 0) else q
            else:
                if rhs == 0:
                    raise _CalcError
                r = abs(val) % abs(rhs)
                val = -r if val < 0 else r
        return val

    def parse_add() -> int:
        nonlocal pos
        val = parse_mul()
        while pos < num_tokens and tokens[pos] in ("+", "-"):
            op = tokens[pos]
            pos += 1
            rhs = parse_mul()
            if op == "+":
                val += rhs
            else:
                val -= rhs
        return val

    try:
        return parse_add()
    except _CalcError:
        return "error"
